// Arma el prompt del Agente Otro (fallback de la rama 'otro'): datos del negocio
// + el mensaje del cliente que no encajo en ninguna rama. El agente decide si
// contesta (cliente frustrado / reclamo / algo del negocio) o si calla (ruido).
const d = $('Leer Intención').first().json;
let filas = [];
try {
  filas = $('Datos Otro').all().map((i) => i.json).filter((r) => r && r.clave && r.valor);
} catch (e) { filas = []; }
const tabla = filas.map((r) => '- ' + r.clave + ': ' + String(r.valor).trim()).join('\n');
return [{ json: {
  ...d,
  infoFilas: filas.length,
  promptOtro: [
    'DATOS DEL NEGOCIO (unica fuente para derivar; no inventes mail/direccion/horarios):',
    tabla || '(sin datos)',
    '',
    'MENSAJE DEL CLIENTE (no encajo en precio, info, producto ni seguimiento):',
    String(d.userMessage || ''),
  ].join('\n'),
} }];
